INSERT INTO public.audits (id, site_id, run_at, score, band, breakdown_json, priorities_json, failures_json, source_file, note) VALUES (1, 1, '2026-11-01T16:13:15.767676+00:00', 62, 'foundation', '{"robots": {"score": 15, "max": 18}, "llms": {"score": 10, "max": 18}, "schema": {"score": 6, "max": 16}, "meta": {"score": 14, "max": 14}, "content": {"score": 10, "max": 12}, "signals": {"score": 5, "max": 6}, "ai_discovery": {"score": 0, "max": 6}, "brand_entity": {"score": 5, "max": 10}, "negative_penalty": -3}'::jsonb, '["Add Organization JSON-LD schema with name, url, and logo", "Add FAQPage schema with site FAQs", "llms.txt has only 0 links. Add more markdown links to key pages for better AI indexing coverage.", "llms.txt should contain markdown links to site pages", "Add sameAs links in Organization schema to Wikipedia, Wikidata, LinkedIn, or Crunchbase for Knowledge Graph disambiguation"]'::jsonb, '["ai_discovery 未通过（0/6）", "llms_txt links_count = 0（has_links = false）", "negative_signals: has_keyword_stuffing = true"]'::jsonb, 'audit-maoxunxing.json', '卫生分，不预测引用（geo-optimizer 作者预注册校准研究：审计分与实际引用无预测关系）') ON CONFLICT (id) DO NOTHING;
