-- GEO 闭环系统 · 种子数据（Supabase / Postgres）
-- 与本地 SQLite 种子（seed.py 灌入的 geo.db）逐项一致：本文件由 geo.db 逐行导出生成，未改动任何数字。
-- 内容口径：双站审计 62/65（卫生分）、冻结 prompt 50 题、CrossAgent 2026-10-29 基线快照 7 条、
-- findings 10、假设卡 4（全 draft）、source_status 7、rules 5。未接入的数据源只有状态、没有假数字。
-- 用法：schema.sql 之后在 SQL Editor 里跑本文件（预期空表；重复跑时 ON CONFLICT (id) DO NOTHING 保证幂等）。

begin;

-- sites（2 行）
SELECT setval(pg_get_serial_sequence('public.sites', 'id'), (SELECT max(id) FROM public.sites));

-- prompts（50 行）
SELECT setval(pg_get_serial_sequence('public.prompts', 'id'), (SELECT max(id) FROM public.prompts));

-- audits（2 行）
SELECT setval(pg_get_serial_sequence('public.audits', 'id'), (SELECT max(id) FROM public.audits));

-- baseline_snapshots（7 行）
SELECT setval(pg_get_serial_sequence('public.baseline_snapshots', 'id'), (SELECT max(id) FROM public.baseline_snapshots));

-- hypotheses（4 行）
SELECT setval(pg_get_serial_sequence('public.hypotheses', 'id'), (SELECT max(id) FROM public.hypotheses));

-- findings（10 行）
SELECT setval(pg_get_serial_sequence('public.findings', 'id'), (SELECT max(id) FROM public.findings));

-- source_status（7 行）
SELECT setval(pg_get_serial_sequence('public.source_status', 'id'), (SELECT max(id) FROM public.source_status));

-- rules（5 行）
SELECT setval(pg_get_serial_sequence('public.rules', 'id'), (SELECT max(id) FROM public.rules));

commit;
